from importlib import import_module
PROVIDERS = {
    'signed': 'wheelmanifest.signed:build',
    'plain': 'wheelmanifest.plain:build',
}
def resolve_renderer(mode):
    module_name, attribute = PROVIDERS[mode].split(':', 1)
    return getattr(import_module(module_name), attribute)

